def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    def evaluate_statement(speaker: str, statement: str) -> bool | None:
        # Ignore statements that mention a day of the week
        for day in days_of_week:
            if day in statement:
                return None
        # Remove trailing period and split
        stmt = statement.strip().rstrip('.')
        parts = stmt.split()
        if len(parts) == 3:
            subject, verb, obj = parts
            if verb not in ('am', 'is'):
                return None
            if obj != 'guilty':
                return None
            subject_name = speaker if subject == 'I' else subject
            return subject_name == scenario
        if len(parts) == 4:
            subject, verb, not_word, obj = parts
            if verb not in ('am', 'is') or not_word != 'not' or obj != 'guilty':
                return None
            subject_name = speaker if subject == 'I' else subject
            return subject_name != scenario
        return None

    for speaker, stmts in statements.items():
        for stmt in stmts:
            val = evaluate_statement(speaker, stmt)
            if val is None:
                continue
            if speaker in liar_count:
                if val:
                    return False
            else:
                if not val:
                    return False
    return True

